 const u8* ARM64XEmitter::AlignCode16()
 {
 	int c = int((u64)m_code & 15);
 	if (c)
 		ReserveCodeSpace(16 - c);
 	return m_code;
 }

 const u8* ARM64XEmitter::AlignCodePage()
 {
 	int page_size = GetMemoryProtectPageSize();
 	int c = int((u64)m_code & (page_size - 1));
