 		case VK_RETURN:
 			returnValue = 0;
 			EditWatch(GetSelectedIndex());
 			return true;
 		case VK_DELETE:
 			returnValue = 0;
 			DeleteWatch(GetSelectedIndex());
 			return true;
 		default:
 			break;
 		}
 		break;
 	case WM_GETDLGCODE:
 		if (lParam && ((MSG *)lParam)->message == WM_KEYDOWN) {
 			if (wParam == VK_TAB || wParam == VK_RETURN || wParam == VK_DELETE) {
 				returnValue = DLGC_WANTMESSAGE;
