 	switch (inst.op) {
 	case IROp::FMin:
 		fp_.FMIN(regs_.F(inst.dest), regs_.F(inst.src1), regs_.F(inst.src2));
 		break;

 	case IROp::FMax:
 		fp_.FMAX(regs_.F(inst.dest), regs_.F(inst.src1), regs_.F(inst.src2));
 		break;

 	default:
 		INVALIDOP;
