+template <typename T>
+inline bool VerifyWait(const T &waitInfo, WaitType waitType, SceUID uid) {
+	u32 error;
+	SceUID waitID = __KernelGetWaitID(waitInfo.threadID, waitType, error);
+	return waitID == uid && error == 0;
