+		regs_.Map(inst);
+		fp_.FDIV(regs_.F(inst.dest), regs_.F(inst.src1), regs_.F(inst.src2));
+		break;
+
 	case IROp::FSqrt:
+		regs_.Map(inst);
+		fp_.FSQRT(regs_.F(inst.dest), regs_.F(inst.src1));
+		break;
+
 	case IROp::FNeg:
-		CompIR_Generic(inst);
+		regs_.Map(inst);
+		fp_.FNEG(regs_.F(inst.dest), regs_.F(inst.src1));
