 void Arm64JitBackend::CompIR_FAssign(IRInst inst) {
 	CONDITIONAL_DISABLE;

 	switch (inst.op) {
 	case IROp::FMov:
+		if (inst.dest != inst.src1) {
+			regs_.Map(inst);
+			fp_.FMOV(regs_.F(inst.dest), regs_.F(inst.src1));
+		}
+		break;
+
 	case IROp::FAbs:
+		regs_.Map(inst);
+		fp_.FABS(regs_.F(inst.dest), regs_.F(inst.src1));
+		break;
+
 	case IROp::FSign:
 		CompIR_Generic(inst);
 		break;

 	default:
 		INVALIDOP;
 		break;
 	}
 }

