+void VertexDecoderJitCache::Jit_ApplyWeights() {
+	int weightSize = 4;
+	switch (dec_->weighttype) {
+	case 1: weightSize = 1; break;
+	case 2: weightSize = 2; break;
+	case 3: weightSize = 4; break;
+	default:
+		_assert_(false);
+		break;
+	}
